import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"组织自动化规则","description":"","frontmatter":{"title":"组织自动化规则","docId":"user.automations.index","translationKey":"user.automations.index","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","translationRevision":"f9ccfae0d2905076b3688226f55ef6869fafcf3b17065e8f9e82085364aafc75","order":10},"headers":[],"relativePath":"zh/user/automations/index.md","filePath":"zh/user/automations/index.md","lastUpdated":1795731074000}`),s={name:`zh/user/automations/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="organize-automations" tabindex="-1">组织自动化规则 <a class="header-anchor" href="#organize-automations" aria-label="Permalink to “组织自动化规则”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>构建小而清晰的规则库，用于响应直播事件。你需要正常运行的桌面宿主。验证上游事件需要真实的<a href="./../live/connections.html">直播连接</a>；插件操作还需要对应插件及服务就绪。</p><h2 id="understand-the-library" tabindex="-1">理解规则库 <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to “理解规则库”">​</a></h2><p><strong>操作</strong> 是可复用的已配置操作，例如写入日志或播放声音。<strong>事件</strong> 选择触发器、筛选条件、冷却时间及关联操作。配置将同一工作流程的定义归组；一次只能激活一个配置包。运行时<a href="./variables.html">变量</a>提供可供多个操作复用的值。</p><ol><li>打开 <strong>自动化</strong>，编辑前先确认当前配置。分别搜索事件和操作，明确自己正在选择哪类记录。</li><li>从<a href="./first-rule.html">第一条日志规则</a>开始。先创建操作，再创建引用该操作的事件。</li><li>选择当前宿主支持的触发器。使用字段选择器为该触发器添加筛选。多个条件会缩小匹配范围，不会改变收到的载荷。</li><li>设置冷却时间及其范围。全局冷却限制所有观众对该规则的触发；按用户冷却则分别跟踪每位观众。</li><li>按顺序关联所需操作。常规模式执行选定列表，随机模式从中选择一个操作。延迟操作会推迟后续操作，不会降低直播接收速度。</li><li>保存，检查显示的定义变更，然后明确启用准备运行的记录。在运行历史中检查操作名称、结果及错误。</li></ol><p>任何比较都可以使用值列表而不是单个值。默认组合方式为“任一”：只要有一个值匹配，条件即满足。若要求每个值都匹配，请将量词切换为“全部”——对于“不等于”，这表示“不等于其中任何一个”。条件还可以命名捕获别名：胜出的值会以 <code>{{ match.&lt;alias&gt; }}</code>（无别名时为 <code>{{ match.&lt;位置&gt; }}</code>）的形式供操作模板使用。在始终必需的条件下方，你最多可以添加四个<strong>备选</strong>：组内所有条件都必须满足，而任意一个组满足即可触发事件。</p><p>测试可能执行配置中的实际效果。按 <strong>运行测试</strong> 或触发事件前，请阅读选中的操作列表，尤其注意音频、HTTP、积分和插件操作。学习阶段请使用日志。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “预期结果与状态”">​</a></h2><p>本地编辑、执行、模板、配置及历史均可使用。插件触发器仅在对应插件已安装并启用时出现。激活状态取决于导入入口及已审核的 enabled 值；确认前应检查事件和动作。事件/操作的 <strong>更改</strong> 面板是<a href="./../cloud/changes.html">本地参考比较</a>，不会自动上传至 Cloud。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to “恢复方法”">​</a></h2><p>没有运行记录时，依次检查当前配置、启用状态、触发器、筛选条件、冷却时间及缺失操作。发生修订冲突时，请读取当前保存的定义并重新审查，不要盲目覆盖他人的更新。大范围修改前，导出已知正常的<a href="./templates.html">配置</a>。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “运行细节”">​</a></h2><p>导入或切换配置前，请阅读<a href="./templates.html#operational-details">各入口的启用规则</a>。切换可能启用曾单独禁用的成员。冷却状态保存在内存中，上限 24 小时；无 uniqueId 的观众共享匿名范围。保留键达到 8,192 时表会清空，因此过载或重启可能允许额外执行。它不是持久配额，也不保证阻止重放。</p><p>在改动真实配置之前先交互式试用:</p>`,15),t(d,{scenario:`automation`,locale:`zh`,panel:`automation`,title:`试用自动化工作区`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">命令行操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “命令行操作”">​</a></h2><p>本指南中的每个操作也可通过 CLI 使用——离线、可编写脚本、适合代理。用法行是解析器语法,在所有语言中保持英文。</p><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>列出自动化规则</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>规则可用的模板上下文</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>读取一条规则</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>创建规则</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>更新规则</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>删除规则 <strong>破坏性</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>启用规则</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>禁用规则</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>对示例事件空跑一条规则</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>手动触发触发器</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>以积分施加管理处罚</td></tr></tbody></table><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>列出已保存的工作流图</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>读取一个图</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>创建或替换图</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>删除图 <strong>破坏性</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>启用图</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>禁用图</td></tr></tbody></table><p>查看<a href="./../../developer/cli.html">完整命令参考</a>了解约定、JSON 输出和破坏性操作标记。</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};